#!/usr/bin/env python3
"""Bake visible pixel bounds; do not sample/import textures during combat."""
import hashlib,json
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]
def main():
    names={s['name'] for s in json.loads((ROOT/'docs/ACTOR-REGISTRATION.json').read_text())['atlases']}
    specs=json.loads((ROOT/'docs/ATLAS-IMPORT.json').read_text());records=[]
    lines=['using System.Collections.Generic;','using UnityEngine;','namespace Starfall {','    // Generated by bake_actor_bounds.py from every nontransparent authored pixel.','    internal static class ActorVisibilityBounds {','        private static readonly Dictionary<string,Rect[]> frames=new Dictionary<string,Rect[]> {']
    for spec in specs:
        if spec['name'] not in names:continue
        name=spec['name'];size=spec['cellSize'];cols=spec['columns'];rows=spec['rows'];path=ROOT/('Assets/Resources/Frontier/Art/'+name+'.png');image=Image.open(path).convert('RGBA');bounds=[]
        for i in range(cols*rows):
            b=image.crop((i%cols*size,i//cols*size,(i%cols+1)*size,(i//cols+1)*size)).getchannel('A').getbbox()
            if not b:raise ValueError('Empty actor '+name)
            bounds.append([b[0],b[1],b[2]-b[0],b[3]-b[1]])
        lines.append('            {"'+name+'",new[]{'+','.join('new Rect('+','.join(map(str,b))+')' for b in bounds)+'}},')
        records.append({'name':name,'cellSize':size,'bounds':bounds,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
    player=[b for r in records if r['name'].startswith('Player') or r['name'] in ('WalkVanguard','WalkRanger','WalkArcanist') for b in r['bounds']]
    left=min(b[0] for b in player);top=min(b[1] for b in player);right=max(b[0]+b[2] for b in player);bottom=max(b[1]+b[3] for b in player)
    lines+=['        };','        internal static readonly Rect PlayerEnvelope=new Rect('+','.join(map(str,[left,top,right-left,bottom-top]))+');','        internal static bool TryBounds(Texture2D sheet,int frame,out Rect bounds) {','            if(sheet!=null) {string name=sheet.name;int slash=name.LastIndexOf(\'/\');if(slash>=0)name=name.Substring(slash+1);Rect[] all;','                if(frames.TryGetValue(name,out all)&&frame>=0&&frame<all.Length){bounds=all[frame];return true;}}','            bounds=new Rect();return false;','        }','    }','}']
    (ROOT/'Assets/Scripts/Frontier/Runtime/ActorVisibilityBounds.cs').write_text('\n'.join(lines)+'\n')
    (ROOT/'docs/ACTOR-VISIBILITY.json').write_text(json.dumps(records,indent=2)+'\n')
    print('PASS',sum(len(r['bounds']) for r in records),'baked actor visibility bounds;',len(records),'atlas hashes; source pixels unchanged.')
if __name__=='__main__':main()
